const cfg = $('Configure Target & Slack Webhook').first().json || {};
const hiring = $('Has New Roles or Comp Changes?').first().json || {};
const ads = $input.first().json || {};

const companyLabel = hiring.companyLabel || hiring.company_label || ads.domain || cfg.targetDomain || 'Stripe';
const boardKey = hiring.boardKey || hiring.board_key || 'GREENHOUSE:stripe';
const opened = Number(hiring.counts?.opened ?? (hiring.eventType === 'JOB_OPENED' ? 1 : 0));
const compChanged = Number(hiring.counts?.compChanged ?? (hiring.eventType === 'JOB_COMP_CHANGED' ? 1 : 0));
const closed = Number(hiring.counts?.closed ?? (hiring.eventType === 'JOB_CLOSED' ? 1 : 0));

const rawEvents = [];
if (Array.isArray(hiring.events)) {
  rawEvents.push(...hiring.events);
} else if (Array.isArray(hiring.windows)) {
  for (const w of hiring.windows) {
    if (Array.isArray(w.emittedEvents)) rawEvents.push(...w.emittedEvents);
  }
} else if (hiring.eventType) {
  rawEvents.push(hiring);
}

const roleBullets = rawEvents.slice(0, 4).map((ev) => {
  const title = ev.title || ev.jobTitle || 'Role Update';
  const kind = ev.eventType || ev.type || 'DIFF';
  const salary = ev.compensationSummary || ev.newCompensation || ev.salaryBand || 'Comp band monitored';
  return `- [${kind}] ${title} (${salary})`;
});
if (roleBullets.length === 0) {
  roleBullets.push(`- ${opened} opened, ${compChanged} salary updates, ${closed} closed on ${boardKey}`);
}

const creatives = Array.isArray(ads.creatives) ? ads.creatives.slice(0, 3) : [];
const adBullets = creatives.map((c) => `- [${c.format || 'AD'}] ${c.headline || c.creative_id} (${c.region || 'US'})`);
const activeRange = ads.estimated_active_ads_range?.label || String(creatives.length);

const slackMessage = [
  `*Competitor GTM Signal: ${companyLabel} (${boardKey})*`,
  `Hiring Diff: *+${opened} opened* | *${compChanged} salary band changes* | *-${closed} closed*`,
  ...roleBullets,
  `Google Ads (${ads.advertiser_name || companyLabel} / ${ads.advertiser_id || 'Verified'}): *${activeRange} active creatives*`,
  ...adBullets,
  `Interactive Watchlist Diff: https://revclamp.com/tools/ats-hiring-watchlist?preset=devtools_outbound_diff&autorun=1`
].join('\n');

const slackBlockKitPayload = {
  text: `Competitor GTM Signal: ${companyLabel} (+${opened} opened, ${compChanged} comp changes, ${activeRange} active ads)`,
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `Competitor GTM Signal: ${companyLabel} (${boardKey})` }
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: slackMessage }
    }
  ]
};

const rawWebhook = String(cfg.slackWebhookUrl || '').trim();
const hasLiveSlackWebhook = rawWebhook.startsWith('https://hooks.slack.com/services/') && !rawWebhook.includes('<');

return [{
  json: {
    companyLabel,
    boardKey,
    opened,
    compChanged,
    closed,
    advertiserId: ads.advertiser_id || null,
    advertiserName: ads.advertiser_name || null,
    estimatedActiveAdsRange: activeRange,
    creativesSampled: creatives.length,
    slackWebhookUrl: rawWebhook,
    hasLiveSlackWebhook,
    slackMessage,
    slackBlockKitPayload
  }
}];
